python3 -c "
import json, glob, os

for d in ['d000','d005','d025','d050','d100']:
    for b in ['mmlu','arc']:
        f = f'/root/contamcal-irt-calibration/eval_results_rerun/olmo2_{d}_s42_{b}/eval_results.json'
        if os.path.exists(f):
            data = json.load(open(f))
            acc_keys = [k for k in data.keys() if 'acc' in k.lower() or 'score' in k.lower() or 'correct' in k.lower() or 'total' in k.lower()]
            acc_vals = {k: data[k] for k in acc_keys if not isinstance(data[k], (dict, list))}
            print(f'olmo2 {d} {b}: {acc_vals}')
        else:
            print(f'olmo2 {d} {b}: NOT_READY')

for d in ['d000','d025','d100']:
    f = f'/root/contamcal-irt-calibration/results/gsm8k_eval/llama3_8b/{d}_s0/eval_results.json'
    if os.path.exists(f):
        data = json.load(open(f))
        acc_keys = [k for k in data.keys() if 'acc' in k.lower() or 'score' in k.lower() or 'correct' in k.lower() or 'total' in k.lower()]
        acc_vals = {k: data[k] for k in acc_keys if not isinstance(data[k], (dict, list))}
        print(f'llama3 {d} gsm8k: {acc_vals}')
    else:
        print(f'llama3 {d} gsm8k: NOT_READY')
"

